using System.Security.Cryptography;
using System.Text.Json.Serialization;
using System.Text;
using Htt.Infrastructure;
using Htt.SharedKernel;
using Htt.Host.Api.MasterData;
using NpgsqlTypes;
using static Htt.Host.Api.MasterData.MasterDataSupport;
using static Htt.Host.Api.Sales.SalesSupport;
namespace Htt.Host.Api.Accounting;
public sealed record BankStatementLineInput(DateOnly Date,decimal Amount,string Description,string Reference="",string? ExternalId=null);
public sealed record BankStatementImportInput(string Reference,DateOnly FromDate,DateOnly ToDate,[property: JsonRequired] decimal OpeningBalance,[property: JsonRequired] decimal ClosingBalance,IReadOnlyList<BankStatementLineInput>? Lines);
public sealed record BankCashAllocationInput(Guid JournalLineId,decimal Amount);
public sealed record BankMatchInput(string Reference,string Reason,IReadOnlyList<BankCashAllocationInput>? Allocations);
public sealed record BankReconcileInput(string Reference,string Reason,IReadOnlyList<BankCashAllocationInput>? OpeningAllocations=null);
public sealed record BankClearingChangeInput(string Reference,string Reason);
internal static class BankReconciliationEndpoints
{
    private const string ReadPermission="accounting.bank_statements.read";
    private static long Version(HttpContext h){if(!long.TryParse(h.Request.Headers.IfMatch.ToString().Trim('"'),out var v)||v<1)throw new BusinessException("version_required","Current statement If-Match required.",428);return v;}
    private static async Task AccessBank(HttpContext h,CompanySession s,Guid bank,string permission,CancellationToken ct)
    {
        foreach(var cap in new[]{ReadPermission,"accounting.banks.read","accounting.ledger.read",permission})if(!Access(h).Has(cap))throw new BusinessException("permission_denied","Bank statement read, directory, ledger and command permissions required.",403);
        await Read(s,"SELECT accounting.require_bank_reconciliation_access(@permission,@bank)",ct,new DbArg("permission",permission),new DbArg("bank",bank));
    }
    private static async Task<Guid> StatementBank(CompanySession s,Guid id,CancellationToken ct)=>(Guid)(await One(s,"SELECT bank_account_id FROM accounting.bank_statements WHERE company_id=@company AND id=@id",ct,new DbArg("id",id)))["bank_account_id"]!;
    private static (string Reference,string Reason) Change(string reference,string reason)=>(Check.Text(reference,"reference",200),Check.Text(reason,"reason",2000));
    private static BankCashAllocationInput[] Allocations(IReadOnlyList<BankCashAllocationInput>? input,bool allowEmpty,int limit=100)
    {
        var rows=input?.ToArray()??[];Check.That(rows.Length<=limit&&(allowEmpty||rows.Length>0)&&rows.All(x=>x is not null&&x.JournalLineId!=Guid.Empty)&&rows.Select(x=>x.JournalLineId).Distinct().Count()==rows.Length,"allocations","Distinct cash-entry IDs and bounded allocations required.");foreach(var row in rows){Check.Amount(row.Amount,"amount",2);Check.That(row.Amount>0,"amount","Positive AUD cents required.");}return rows.OrderBy(x=>x.JournalLineId).ToArray();
    }
    public static void Map(RouteGroupBuilder g)
    {
        g=g.MapGroup("").AddEndpointFilter(async(context,next)=>{var access=Access(context.HttpContext);foreach(var cap in new[]{ReadPermission,"accounting.banks.read","accounting.ledger.read"})if(!access.Has(cap))throw new BusinessException("permission_denied","Statement, bank-directory and ledger read permissions required.",403);return await next(context);});
        g.MapPost("/bank-accounts/{id:guid}/statements/import",async(Guid id,BankStatementImportInput input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>await Import(id,input,"JSON",null,h,s,idem,ct)).WithMetadata(new Permission("accounting.bank_statements.import"));
        g.MapPost("/bank-accounts/{id:guid}/statements/import-csv",ImportCsv).WithMetadata(new Permission("accounting.bank_statements.import"));
        g.MapGet("/bank-accounts/{id:guid}/statements",async(Guid id,int? page,int? pageSize,HttpContext h,CompanySession s,CancellationToken ct)=>{await AccessBank(h,s,id,ReadPermission,ct);var(offset,size)=Page(page,pageSize);return Results.Ok(new{items=(await Read(s,"SELECT s.id,s.reference,s.from_date,s.to_date,s.opening_balance,s.closing_balance,s.source_format,s.source_hash,s.line_count,c.state,c.version,s.created_at FROM accounting.bank_statements s JOIN accounting.bank_statement_controls c ON c.company_id=s.company_id AND c.id=s.id WHERE s.company_id=@company AND s.bank_account_id=@bank ORDER BY s.to_date DESC,s.created_at DESC,s.id LIMIT @size OFFSET @offset",ct,new DbArg("bank",id),new DbArg("size",size),new DbArg("offset",offset))).Select(PublicRow),page=page??1,pageSize=size});}).WithMetadata(new Permission(ReadPermission));
        g.MapGet("/bank-statements/{id:guid}",async(Guid id,int? page,int? pageSize,HttpContext h,CompanySession s,CancellationToken ct)=>{await AccessBank(h,s,await StatementBank(s,id,ct),ReadPermission,ct);return Results.Ok(await View(s,id,page,pageSize,ct));}).WithMetadata(new Permission(ReadPermission));
        g.MapGet("/bank-statements/{id:guid}/source",async(Guid id,HttpContext h,CompanySession s,CancellationToken ct)=>{await AccessBank(h,s,await StatementBank(s,id,ct),ReadPermission,ct);var row=await One(s,"SELECT source_content,source_format FROM accounting.bank_statements WHERE company_id=@company AND id=@id",ct,new DbArg("id",id));var csv=(string)row["source_format"]! == "CSV";return Results.File((byte[])row["source_content"]!,csv?"text/csv; charset=utf-8":"application/json",$"statement-{id}."+(csv?"csv":"json"));}).WithMetadata(new Permission(ReadPermission));
        g.MapGet("/bank-statement-lines/{id:guid}/candidates",Candidates).WithMetadata(new Permission(ReadPermission));
        g.MapPost("/bank-statement-lines/{id:guid}/matches",Match).WithMetadata(new Permission("accounting.bank_statements.match"));
        g.MapPost("/bank-matches/{id:guid}/release",Release).WithMetadata(new Permission("accounting.bank_statements.match"));
        g.MapPost("/bank-statements/{id:guid}/reconcile",Reconcile).WithMetadata(new Permission("accounting.bank_statements.reconcile"));
        g.MapPost("/bank-statements/{id:guid}/void",Void).WithMetadata(new Permission("accounting.bank_statements.void"));
        g.MapPost("/bank-reconciliations/{id:guid}/reopen",Reopen).WithMetadata(new Permission("accounting.bank_statements.reopen"));
        g.MapGet("/bank-reconciliations/{id:guid}",ReconciliationView).WithMetadata(new Permission(ReadPermission));
        g.MapGet("/bank-accounts/{id:guid}/cash-clearing",CashClearing).WithMetadata(new Permission(ReadPermission));
    }
    private static async Task<IResult> ImportCsv(Guid id,string reference,DateOnly fromDate,DateOnly toDate,decimal openingBalance,decimal closingBalance,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
    {
        await AccessBank(h,s,id,"accounting.bank_statements.import",ct);Check.That(h.Request.ContentType?.Split(';')[0].Trim().Equals("text/csv",StringComparison.OrdinalIgnoreCase)==true,"contentType","Use raw UTF-8 text/csv.");if(h.Request.ContentLength>BankStatementCsv.MaxBytes)throw new BusinessException("file_too_large","CSV exceeds 2 MiB.",413);using var memory=new MemoryStream();var buffer=new byte[8192];int read;while((read=await h.Request.Body.ReadAsync(buffer,ct))>0){if(memory.Length+read>BankStatementCsv.MaxBytes)throw new BusinessException("file_too_large","CSV exceeds 2 MiB.",413);await memory.WriteAsync(buffer.AsMemory(0,read),ct);}var bytes=memory.ToArray();return await Import(id,new(reference,fromDate,toDate,openingBalance,closingBalance,BankStatementCsv.Parse(bytes)),"CSV",bytes,h,s,idem,ct);
    }
    private static async Task<IResult> Import(Guid bank,BankStatementImportInput input,string format,byte[]? bytes,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
    {
        await AccessBank(h,s,bank,"accounting.bank_statements.import",ct);var reference=Check.Text(input.Reference,"reference",200);Check.That(input.FromDate!=DateOnly.MinValue&&input.ToDate>=input.FromDate&&input.ToDate.DayNumber-input.FromDate.DayNumber<=366,"dates","Use an inclusive statement period up to 367 calendar dates.");Signed(input.OpeningBalance,"openingBalance");Signed(input.ClosingBalance,"closingBalance");Check.That(input.Lines is not null&&input.Lines.Count<=5000&&input.Lines.All(x=>x is not null),"lines","Supply 0..5000 statement rows.");var lines=input.Lines!.Select(x=>x with{Description=Check.Optional(x.Description,"description",1000)??"",Reference=Check.Optional(x.Reference,"reference",200)??"",ExternalId=Check.Optional(x.ExternalId,"externalId",200)}).ToArray();foreach(var row in lines){Signed(row.Amount,"amount");Check.That(row.Amount!=0&&row.Date>=input.FromDate&&row.Date<=input.ToDate,"lines","Nonzero amount and date inside the statement required.");}Check.That(lines.Where(x=>x.ExternalId is not null).Select(x=>x.ExternalId).Distinct().Count()==lines.Count(x=>x.ExternalId is not null),"externalId","Duplicate external IDs in file.");Check.That(input.OpeningBalance+lines.Sum(x=>x.Amount)==input.ClosingBalance,"closingBalance","Opening plus signed transactions must equal closing.");bytes??=Encoding.UTF8.GetBytes(Json(lines));Check.That(bytes.Length<=BankStatementCsv.MaxBytes,"file","Import source exceeds 2 MiB.");var hash=Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant();var route=$"POST /bank-accounts/{bank}/statements/import-{format}";
        var result=await idem.ExecuteAsync(route,h.Request.Headers["Idempotency-Key"].ToString(),Json(new{bank,reference,input.FromDate,input.ToDate,input.OpeningBalance,input.ClosingBalance,format,hash,lines}),async()=>{var row=await One(s,"SELECT * FROM accounting.import_bank_statement(@bank,@reference,@from,@to,@opening,@closing,@format,@hash,@lines,@source)",ct,new DbArg("bank",bank),new DbArg("reference",reference),new DbArg("from",input.FromDate),new DbArg("to",input.ToDate),new DbArg("opening",input.OpeningBalance),new DbArg("closing",input.ClosingBalance),new DbArg("format",format),new DbArg("hash",hash),new DbArg("lines",Json(lines),NpgsqlDbType.Jsonb),new DbArg("source",bytes,NpgsqlDbType.Bytea));var id=(Guid)row["id"]!;if((bool)row["created"]!)await Sql.AuditAsync(s,"accounting.bank_statement_imported","bank_statement",id,h.TraceIdentifier,ct,new{bank,reference,hash,lineCount=lines.Length});return ApiJson.Stored(await View(s,id,null,null,ct));},ct);return ApiJson.Result(result);
    }
    private static void Signed(decimal value,string field){Check.That(value is>=-999999999999999999.99m and<=999999999999999999.99m&&decimal.Round(value,2)==value,field,"Signed AUD cents within storage limits required.");}
    private static async Task<IResult> Match(Guid id,BankMatchInput input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
    {
        var source=await One(s,"SELECT bank_account_id,statement_id FROM accounting.bank_statement_lines WHERE company_id=@company AND id=@id",ct,new DbArg("id",id));await AccessBank(h,s,(Guid)source["bank_account_id"]!,"accounting.bank_statements.match",ct);var expected=Version(h);var(reference,reason)=Change(input.Reference,input.Reason);var rows=Allocations(input.Allocations,false);var result=await idem.ExecuteAsync($"POST /bank-statement-lines/{id}/matches",h.Request.Headers["Idempotency-Key"].ToString(),Json(new{id,expected,reference,reason,rows}),async()=>{var mid=(Guid)(await One(s,"SELECT accounting.match_bank_line(@id,@expected,@reference,@reason,@items) AS id",ct,new DbArg("id",id),new DbArg("expected",expected),new DbArg("reference",reference),new DbArg("reason",reason),new DbArg("items",Json(rows),NpgsqlDbType.Jsonb)))["id"]!;await Sql.AuditAsync(s,"accounting.bank_matched","bank_match",mid,h.TraceIdentifier,ct,new{statementLineId=id,reference});return ApiJson.Stored(new{id=mid,statement=await View(s,(Guid)source["statement_id"]!,null,null,ct)});},ct);return ApiJson.Result(result);
    }
    private static async Task<IResult> Release(Guid id,BankClearingChangeInput input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
    {
        var m=await One(s,"SELECT l.bank_account_id,l.statement_id FROM accounting.bank_matches m JOIN accounting.bank_statement_lines l ON l.company_id=m.company_id AND l.id=m.statement_line_id WHERE m.company_id=@company AND m.id=@id",ct,new DbArg("id",id));await AccessBank(h,s,(Guid)m["bank_account_id"]!,"accounting.bank_statements.match",ct);return await ChangeCommand(id,input,"release","accounting.release_bank_match","accounting.bank_match_released",(Guid)m["statement_id"]!,h,s,idem,ct);
    }
    private static async Task<IResult> Reconcile(Guid id,BankReconcileInput input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
    {
        await AccessBank(h,s,await StatementBank(s,id,ct),"accounting.bank_statements.reconcile",ct);var expected=Version(h);var(reference,reason)=Change(input.Reference,input.Reason);var rows=Allocations(input.OpeningAllocations,true,5000);var result=await idem.ExecuteAsync($"POST /bank-statements/{id}/reconcile",h.Request.Headers["Idempotency-Key"].ToString(),Json(new{id,expected,reference,reason,rows}),async()=>{var rid=(Guid)(await One(s,"SELECT accounting.finalize_bank_reconciliation(@id,@expected,@reference,@reason,@items) AS id",ct,new DbArg("id",id),new DbArg("expected",expected),new DbArg("reference",reference),new DbArg("reason",reason),new DbArg("items",Json(rows),NpgsqlDbType.Jsonb)))["id"]!;await Sql.AuditAsync(s,"accounting.bank_reconciled","bank_reconciliation",rid,h.TraceIdentifier,ct,new{statementId=id,reference});return ApiJson.Stored(new{id=rid,statement=await View(s,id,null,null,ct)});},ct);return ApiJson.Result(result);
    }
    private static async Task<IResult> Reopen(Guid id,BankClearingChangeInput input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
    {
        var r=await One(s,"SELECT bank_account_id,statement_id FROM accounting.bank_reconciliations WHERE company_id=@company AND id=@id",ct,new DbArg("id",id));await AccessBank(h,s,(Guid)r["bank_account_id"]!,"accounting.bank_statements.reopen",ct);return await ChangeCommand(id,input,"reopen","accounting.reopen_bank_reconciliation","accounting.bank_reconciliation_reopened",(Guid)r["statement_id"]!,h,s,idem,ct);
    }
    private static async Task<IResult> Void(Guid id,BankClearingChangeInput input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct){await AccessBank(h,s,await StatementBank(s,id,ct),"accounting.bank_statements.void",ct);return await ChangeCommand(id,input,"void","accounting.void_bank_statement","accounting.bank_statement_voided",id,h,s,idem,ct);}
    private static async Task<IResult> ChangeCommand(Guid id,BankClearingChangeInput input,string operation,string function,string action,Guid statement,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
    {
        var expected=Version(h);var(reference,reason)=Change(input.Reference,input.Reason);var route=operation=="release"?$"POST /bank-matches/{id}/release":operation=="reopen"?$"POST /bank-reconciliations/{id}/reopen":$"POST /bank-statements/{id}/void";var result=await idem.ExecuteAsync(route,h.Request.Headers["Idempotency-Key"].ToString(),Json(new{id,expected,reference,reason}),async()=>{var changed=(Guid)(await One(s,$"SELECT {function}(@id,@expected,@reference,@reason) AS id",ct,new DbArg("id",id),new DbArg("expected",expected),new DbArg("reference",reference),new DbArg("reason",reason)))["id"]!;await Sql.AuditAsync(s,action,operation=="release"?"bank_match_release":operation=="reopen"?"bank_reconciliation_reopen":"bank_statement",changed,h.TraceIdentifier,ct,new{statementId=statement,reference,reason});return ApiJson.Stored(new{id=changed,statement=await View(s,statement,null,null,ct)},200);},ct);return ApiJson.Result(result);
    }
    private static async Task<object> View(CompanySession s,Guid id,int? page,int? pageSize,CancellationToken ct)
    {
        var(offset,size)=Page(page,pageSize);var json=await One(s,"""
        WITH st AS(SELECT s.id,s.bank_account_id,s.reference,s.from_date,s.to_date,s.opening_balance,s.closing_balance,s.source_format,s.source_hash,s.line_count,c.state,c.version FROM accounting.bank_statements s JOIN accounting.bank_statement_controls c ON c.company_id=s.company_id AND c.id=s.id WHERE s.company_id=@company AND s.id=@id), lines AS MATERIALIZED(SELECT l.*,coalesce((SELECT sum(a.amount) FROM accounting.bank_match_allocations a JOIN accounting.active_bank_matches m ON m.company_id=a.company_id AND m.id=a.match_id WHERE m.company_id=l.company_id AND m.statement_line_id=l.id),0) AS matched FROM accounting.bank_statement_lines l WHERE l.company_id=@company AND l.statement_id=@id), paged AS(SELECT * FROM lines ORDER BY line_no LIMIT @size OFFSET @offset)
        SELECT jsonb_build_object('statement',jsonb_build_object('id',st.id,'bankAccountId',st.bank_account_id,'reference',st.reference,'fromDate',st.from_date,'toDate',st.to_date,'openingBalance',st.opening_balance::text,'closingBalance',st.closing_balance::text,'sourceFormat',st.source_format,'sourceHash',st.source_hash,'lineCount',st.line_count,'state',st.state,'version',st.version),'unmatchedCount',(SELECT count(*) FROM lines WHERE matched<abs(amount)),'reconciliations',coalesce((SELECT jsonb_agg(jsonb_build_object('id',r.id,'active',u.id IS NULL,'createdAt',r.created_at) ORDER BY r.created_at,r.id) FROM accounting.bank_reconciliations r LEFT JOIN accounting.bank_reconciliation_reopens u ON u.company_id=r.company_id AND u.reconciliation_id=r.id WHERE r.company_id=@company AND r.statement_id=@id),'[]'::jsonb),'lines',coalesce((SELECT jsonb_agg(jsonb_build_object('id',l.id,'lineNo',l.line_no,'date',l.transaction_date,'amount',l.amount::text,'description',l.description,'reference',l.reference,'externalId',l.external_id,'possibleDuplicateCount',CASE WHEN l.external_id IS NOT NULL THEN 0 ELSE(SELECT count(*) FROM accounting.bank_statement_lines other JOIN accounting.bank_statement_controls oc ON oc.company_id=other.company_id AND oc.id=other.statement_id WHERE other.company_id=l.company_id AND other.bank_account_id=l.bank_account_id AND other.id<>l.id AND other.transaction_date=l.transaction_date AND other.amount=l.amount AND other.reference=l.reference AND other.description=l.description AND oc.state<>'VOID')END,'matchedAmount',l.matched::text,'status',CASE WHEN l.matched=0 THEN 'UNMATCHED' WHEN l.matched=abs(l.amount) THEN 'MATCHED' ELSE 'PARTIAL' END,'matches',coalesce((SELECT jsonb_agg(jsonb_build_object('id',m.id,'reference',m.reference,'released',u.id IS NOT NULL,'allocations',(SELECT jsonb_agg(jsonb_build_object('journalLineId',a.journal_line_id,'amount',a.amount::text) ORDER BY a.id) FROM accounting.bank_match_allocations a WHERE a.company_id=m.company_id AND a.match_id=m.id)) ORDER BY m.created_at,m.id) FROM accounting.bank_matches m LEFT JOIN accounting.bank_match_releases u ON u.company_id=m.company_id AND u.match_id=m.id WHERE m.company_id=l.company_id AND m.statement_line_id=l.id),'[]'::jsonb)) ORDER BY l.line_no) FROM paged l),'[]'::jsonb),'page',@page,'pageSize',@size,'snapshotAt',statement_timestamp())::text AS result FROM st
        """,ct,new DbArg("id",id),new DbArg("size",size),new DbArg("offset",offset),new DbArg("page",page??1));return Element(json["result"]!);
    }
    private static async Task<IResult> Candidates(Guid id,string? q,int? page,int? pageSize,HttpContext h,CompanySession s,CancellationToken ct)
    {
        var l=await One(s,"SELECT l.bank_account_id,l.amount,l.transaction_date,st.to_date,ctl.state,abs(l.amount)-coalesce((SELECT sum(a.amount) FROM accounting.active_bank_matches m JOIN accounting.bank_match_allocations a ON a.company_id=m.company_id AND a.match_id=m.id WHERE m.company_id=l.company_id AND m.statement_line_id=l.id),0) AS remaining FROM accounting.bank_statement_lines l JOIN accounting.bank_statements st ON st.company_id=l.company_id AND st.id=l.statement_id JOIN accounting.bank_statement_controls ctl ON ctl.company_id=l.company_id AND ctl.id=l.statement_id WHERE l.company_id=@company AND l.id=@id",ct,new DbArg("id",id));await AccessBank(h,s,(Guid)l["bank_account_id"]!,ReadPermission,ct);var(offset,size)=Page(page,pageSize);var text=Check.Optional(q,"q",100)??"";return Results.Ok(new{items=(await Read(s,"SELECT p.*,p.amount-p.reserved_amount AS available_amount,(p.amount-p.reserved_amount=@remaining) AS exact_amount FROM accounting.bank_cash_positions p WHERE p.company_id=@company AND p.bank_account_id=@bank AND @state='OPEN' AND @remaining>0 AND sign(p.signed_amount)=sign(@amount) AND p.posting_date<=@to AND p.amount>p.reserved_amount AND(@q='' OR strpos(lower(coalesce(p.source_number,'')||' '||p.description),lower(@q))>0) ORDER BY exact_amount DESC,abs(p.posting_date-@date),p.posting_date,p.id LIMIT @size OFFSET @offset",ct,new DbArg("bank",l["bank_account_id"]),new DbArg("amount",l["amount"]),new DbArg("remaining",l["remaining"]),new DbArg("state",l["state"]),new DbArg("date",l["transaction_date"]),new DbArg("to",l["to_date"]),new DbArg("q",text),new DbArg("size",size),new DbArg("offset",offset))).Select(PublicRow),page=page??1,pageSize=size});
    }
    private static async Task<IResult> CashClearing(Guid id,int? page,int? pageSize,HttpContext h,CompanySession s,CancellationToken ct)
    {
        await AccessBank(h,s,id,ReadPermission,ct);var(offset,size)=Page(page,pageSize);return Results.Ok(new{currency="AUD",items=(await Read(s,"SELECT p.*,p.amount-p.reserved_amount AS available_amount,p.amount-p.cleared_amount AS uncleared_amount FROM accounting.bank_cash_positions p WHERE p.company_id=@company AND p.bank_account_id=@bank ORDER BY p.posting_date,p.id LIMIT @size OFFSET @offset",ct,new DbArg("bank",id),new DbArg("size",size),new DbArg("offset",offset))).Select(PublicRow),page=page??1,pageSize=size});
    }
    private static async Task<IResult> ReconciliationView(Guid id,int? page,int? pageSize,HttpContext h,CompanySession s,CancellationToken ct)
    {
        var bank=(Guid)(await One(s,"SELECT bank_account_id FROM accounting.bank_reconciliations WHERE company_id=@company AND id=@id",ct,new DbArg("id",id)))["bank_account_id"]!;await AccessBank(h,s,bank,ReadPermission,ct);var(offset,size)=Page(page,pageSize);return Results.Ok(new{reconciliation=PublicRow(await One(s,"SELECT r.*,u.id AS reopen_id FROM accounting.bank_reconciliations r LEFT JOIN accounting.bank_reconciliation_reopens u ON u.company_id=r.company_id AND u.reconciliation_id=r.id WHERE r.company_id=@company AND r.id=@id",ct,new DbArg("id",id))),matches=(await Read(s,"SELECT m.match_id,a.journal_line_id,a.amount FROM accounting.bank_reconciliation_matches m JOIN accounting.bank_match_allocations a ON a.company_id=m.company_id AND a.match_id=m.match_id WHERE m.company_id=@company AND m.reconciliation_id=@id ORDER BY m.match_id,a.id LIMIT @size OFFSET @offset",ct,new DbArg("id",id),new DbArg("size",size),new DbArg("offset",offset))).Select(PublicRow),openingAllocations=(await Read(s,"SELECT journal_line_id,amount FROM accounting.bank_opening_allocations WHERE company_id=@company AND reconciliation_id=@id ORDER BY id LIMIT @size OFFSET @offset",ct,new DbArg("id",id),new DbArg("size",size),new DbArg("offset",offset))).Select(PublicRow),outstanding=(await Read(s,"SELECT o.journal_line_id,o.signed_remaining,p.posting_date,p.source_document_id,p.source_number,p.posting_kind FROM accounting.bank_reconciliation_outstanding o JOIN accounting.bank_cash_positions p ON p.company_id=o.company_id AND p.id=o.journal_line_id WHERE o.company_id=@company AND o.reconciliation_id=@id ORDER BY p.posting_date,o.id LIMIT @size OFFSET @offset",ct,new DbArg("id",id),new DbArg("size",size),new DbArg("offset",offset))).Select(PublicRow),page=page??1,pageSize=size});
    }
}
